/**
 * Applies pending SQL migrations from ./drizzle (generated by drizzle-kit).
 *
 * Runs on a dedicated connection (not the shared pool) because MySQL named locks are
 * connection-scoped: GET_LOCK serialises concurrent boots (several workers, a deploy
 * overlapping a restart) so only one process migrates at a time; the others wait and then
 * find nothing pending. Framework-free on purpose — usable from instrumentation and CLI scripts.
 */
import path from "node:path";
import { drizzle } from "drizzle-orm/mysql2";
import { readMigrationFiles, type MigrationConfig } from "drizzle-orm/migrator";
import { migrate } from "drizzle-orm/mysql2/migrator";
import mysql from "mysql2/promise";

const MIGRATIONS_TABLE = "__drizzle_migrations";

export interface MigrationOptions {
  /** defaults to <cwd>/drizzle (traced into the standalone build via next.config outputFileTracingIncludes) */
  migrationsFolder?: string;
  /** how long to wait for another process holding the migration lock (seconds) */
  lockTimeoutSec?: number;
  databaseUrl?: string;
}

export interface MigrationResult {
  status: "applied" | "up-to-date" | "lock-timeout";
  /** migrations applied by this call */
  applied: number;
  /** migrations known on disk */
  total: number;
  durationMs: number;
}

export async function runMigrations(opts: MigrationOptions = {}): Promise<MigrationResult> {
  const started = Date.now();
  const url = opts.databaseUrl ?? process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");

  const config: MigrationConfig = {
    migrationsFolder: opts.migrationsFolder ?? path.join(process.cwd(), "drizzle"),
    migrationsTable: MIGRATIONS_TABLE,
  };
  const files = readMigrationFiles(config);

  const conn = await mysql.createConnection({
    uri: url,
    charset: "utf8mb4_unicode_ci",
    timezone: "Z",
    connectTimeout: 10_000,
    multipleStatements: false,
  });

  try {
    // Lock names are server-wide in MySQL/MariaDB, so scope them to the database.
    const [[{ dbName }]] = (await conn.query("SELECT DATABASE() AS dbName")) as unknown as [[{ dbName: string | null }]];
    const lockName = `${dbName ?? "app"}:migrations`.slice(0, 64);
    const [[{ got }]] = (await conn.query("SELECT GET_LOCK(?, ?) AS got", [
      lockName,
      opts.lockTimeoutSec ?? 60,
    ])) as unknown as [[{ got: number | null }]];
    if (got !== 1) {
      return { status: "lock-timeout", applied: 0, total: files.length, durationMs: Date.now() - started };
    }

    try {
      const before = await appliedCount(conn);
      await migrate(drizzle(conn), config);
      const after = await appliedCount(conn);
      const applied = Math.max(0, after - before);
      return {
        status: applied > 0 ? "applied" : "up-to-date",
        applied,
        total: files.length,
        durationMs: Date.now() - started,
      };
    } finally {
      await conn.query("SELECT RELEASE_LOCK(?)", [lockName]).catch(() => undefined);
    }
  } finally {
    await conn.end().catch(() => undefined);
  }
}

async function appliedCount(conn: mysql.Connection): Promise<number> {
  const [rows] = (await conn.query(
    "SELECT COUNT(*) AS n FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = ?",
    [MIGRATIONS_TABLE],
  )) as unknown as [{ n: number | string }[]];
  if (Number(rows[0]?.n ?? 0) === 0) return 0;
  const [counted] = (await conn.query(`SELECT COUNT(*) AS n FROM \`${MIGRATIONS_TABLE}\``)) as unknown as [
    { n: number | string }[],
  ];
  return Number(counted[0]?.n ?? 0);
}
